import { defineStore } from 'pinia'
import { computed, ref } from 'vue'

export interface SpeechReplaySegment {
  sequence: number
  audio: AudioBuffer
  text: string
}

type ReplayHandler = (messageId: string, segments: SpeechReplaySegment[]) => Promise<void>

const MAX_REPLAY_MESSAGES = 50

export const useChatSpeechReplayStore = defineStore('chat-speech-replay', () => {
  const replayableMessageIds = ref<Record<string, true>>({})
  const replayingMessageId = ref<string>()
  const replayVersion = ref(0)

  const segmentMap = new Map<string, Map<number, SpeechReplaySegment>>()
  let replayHandler: ReplayHandler | undefined

  const replayableCount = computed(() => Object.keys(replayableMessageIds.value).length)

  function setReplayHandler(handler?: ReplayHandler) {
    replayHandler = handler
  }

  function trimOverflow() {
    const messageIds = Object.keys(replayableMessageIds.value)
    if (messageIds.length <= MAX_REPLAY_MESSAGES)
      return

    const overflowIds = messageIds.slice(0, messageIds.length - MAX_REPLAY_MESSAGES)
    for (const messageId of overflowIds) {
      segmentMap.delete(messageId)
      const next = { ...replayableMessageIds.value }
      delete next[messageId]
      replayableMessageIds.value = next
    }
  }

  function registerReplaySegment(messageId: string, sequence: number, audio: AudioBuffer, text: string) {
    if (!messageId)
      return

    let segments = segmentMap.get(messageId)
    if (!segments) {
      segments = new Map()
      segmentMap.set(messageId, segments)
    }

    segments.set(sequence, {
      sequence,
      audio,
      text,
    })

    replayableMessageIds.value = {
      ...replayableMessageIds.value,
      [messageId]: true,
    }
    trimOverflow()
    replayVersion.value += 1
  }

  function hasReplay(messageId?: string) {
    if (!messageId)
      return false
    return !!replayableMessageIds.value[messageId]
  }

  function getReplaySegments(messageId: string) {
    const segments = segmentMap.get(messageId)
    if (!segments)
      return []

    return [...segments.values()].sort((a, b) => a.sequence - b.sequence)
  }

  async function replayMessage(messageId?: string) {
    if (!messageId || !replayHandler || replayingMessageId.value === messageId)
      return

    const segments = getReplaySegments(messageId)
    if (segments.length === 0)
      return

    replayingMessageId.value = messageId
    try {
      await replayHandler(messageId, segments)
    }
    finally {
      if (replayingMessageId.value === messageId)
        replayingMessageId.value = undefined
    }
  }

  function clearReplay(messageId?: string) {
    if (!messageId)
      return

    if (!segmentMap.delete(messageId))
      return

    const next = { ...replayableMessageIds.value }
    delete next[messageId]
    replayableMessageIds.value = next
    replayVersion.value += 1
  }

  function clearAll() {
    segmentMap.clear()
    replayableMessageIds.value = {}
    replayingMessageId.value = undefined
    replayVersion.value += 1
  }

  return {
    replayVersion,
    replayableCount,
    replayingMessageId,
    setReplayHandler,
    registerReplaySegment,
    hasReplay,
    replayMessage,
    clearReplay,
    clearAll,
  }
})
